import 'dart:convert';

/// Model representing a QR Pairing Ticket generated by a Parent.
/// Mirrors `PairingTicketResponseDto` from ASP.NET Core backend.
class PairingTicketModel {
  final String ticketId;
  final String pairingCode;
  final String qrPayload;
  final int childId;
  final String childName;
  final DateTime expiresAt;

  const PairingTicketModel({
    required this.ticketId,
    required this.pairingCode,
    required this.qrPayload,
    required this.childId,
    required this.childName,
    required this.expiresAt,
  });

  factory PairingTicketModel.fromJson(Map<String, dynamic> json) {
    return PairingTicketModel(
      ticketId: json['ticketId'] as String? ?? '',
      pairingCode: json['pairingCode'] as String? ?? '',
      qrPayload: json['qrPayload'] as String? ?? '',
      childId: json['childId'] as int? ?? 0,
      childName: json['childName'] as String? ?? '',
      expiresAt: json['expiresAt'] != null
          ? DateTime.tryParse(json['expiresAt'] as String)?.toUtc() ?? DateTime.now().toUtc()
          : DateTime.now().toUtc(),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'ticketId': ticketId,
      'pairingCode': pairingCode,
      'qrPayload': qrPayload,
      'childId': childId,
      'childName': childName,
      'expiresAt': expiresAt.toIso8601String(),
    };
  }

  bool get isExpired => DateTime.now().toUtc().isAfter(expiresAt);

  Duration get remainingDuration {
    final diff = expiresAt.difference(DateTime.now().toUtc());
    return diff.isNegative ? Duration.zero : diff;
  }

  /// Extracts the effective pairing code or ticket ID from raw scanned text or manual input.
  /// Handles both JSON QR payloads: `{"ticketId":"...","pairingCode":"PAIR-XXXX",...}`
  /// and plain code inputs like `"PAIR-XXXX"` or ticket hex.
  static String extractPairingCode(String rawInput) {
    final trimmed = rawInput.trim();
    if (trimmed.isEmpty) return '';

    if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
      try {
        final decoded = jsonDecode(trimmed);
        if (decoded is Map<String, dynamic>) {
          if (decoded['pairingCode'] is String && (decoded['pairingCode'] as String).isNotEmpty) {
            return (decoded['pairingCode'] as String).trim();
          }
          if (decoded['ticketId'] is String && (decoded['ticketId'] as String).isNotEmpty) {
            return (decoded['ticketId'] as String).trim();
          }
        }
      } catch (_) {
        // Fall back to trimmed string if not valid JSON
      }
    }

    return trimmed;
  }
}

